#version 330
#extension GL_ARB_separate_shader_objects : require

#include <minecraft:globals.glsl>
#include <sun:bus_read.glsl>
#include <sun:atmosphere.glsl>
#include <sun:fog.glsl>
#include <sun:water.glsl>
#include <sun:light_code.glsl>
#include <sun:lighting.glsl>

// The atmosphere: a scattered sky in place of the vanilla one, with the vanilla moon and stars on top,
// and the distance fog of the world and the clouds turned to that sky instead of the flat fog color.
// Opaque terrain is relit first (sun:lighting.glsl), from the light levels in its alpha.
// Water pixels are tagged in alpha for the water pass: 0.5 for a horizontal surface, 0.25 for a side.
uniform sampler2D InSampler;
uniform sampler2D DepthSampler;
uniform sampler2D LightSampler;

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

void main() {
    ivec2 pixel = ivec2(texCoord * vec2(textureSize(InSampler, 0)));
    vec4 original = texelFetch(InSampler, pixel, 0);

    // Water markers (sun:water.glsl): a marker pixel takes the vanilla water of its neighbours, and both
    // the marker and the pixel to its right are water.
    float waterData = 0.0;
    if (sun_is_water_marker(original, pixel.x)) {
        waterData = original.b;
        vec4 right = texelFetch(InSampler, pixel + ivec2(1, 0), 0);
        vec4 left = texelFetch(InSampler, pixel - ivec2(1, 0), 0);
        bool leftIsWater = sun_is_water_marker(texelFetch(InSampler, pixel - ivec2(2, 0), 0), pixel.x - 2);
        original = leftIsWater ? 0.5 * (left + right) : right;
    } else if ((pixel.x & 1) == 1) {
        vec4 left = texelFetch(InSampler, pixel - ivec2(1, 0), 0);
        if (sun_is_water_marker(left, pixel.x - 1)) {
            waterData = left.b;
        }
    }

    vec3 color = original.rgb;
    SunBus bus = sun_read_bus(InSampler);
    bool inAir = bus.present && sun_in_air(bus);
    float depth = texture(DepthSampler, texCoord).r;
    bool sky = depth <= 0.0;   // reversed depth: nothing drawn here
    vec3 position = bus.viewToWorld * sun_view_position(bus, texCoord, sky ? 0.5 : depth);
    vec3 faceNormal = normalize(cross(dFdx(position), dFdy(position)));   // derivatives: before any branch

    if (inAir) {
        float exposure = sun_unpack_float(texelFetch(LightSampler, ivec2(0, 0), 0));
        vec3 dir = normalize(position);

        vec3 transmittance;
        vec3 skyLinear = sun_sky(dir, bus.sunDirection, bus.rainBrightness, sun_altitude(float(CameraBlockPos.y) - CameraOffset.y), transmittance);
        vec3 discLinear = sun_sun_disc(dir, bus.sunDirection, transmittance, bus.rainBrightness);
        vec3 skyColor = sun_tonemap(skyLinear * exposure);
        vec3 skyWithSun = sun_tonemap((skyLinear + discLinear) * exposure);

        if (sky) {
            // The frame was cleared to the fog color: whatever is above it is the moon and the stars.
            color = skyWithSun + max(original.rgb - bus.fogColor, 0.0);
        } else {
            // What the alpha says (sun:light_code.glsl): translucent in front of the clear color, opaque terrain
            // with its light levels, or anything else opaque. Water over the void has the alpha of the water
            // texture, 180/255; over anything else, the blend makes it meaningless.
            float a = original.a;
            vec2 levels;
            bool terrain = sun_decode_light(a, levels) && waterData == 0.0;
            bool overClear = waterData > 0.0 ? a < 0.72 : a < 204.5 / 255.0;
            float alpha = overClear ? a : 1.0;
            float cameraY = float(CameraBlockPos.y) - CameraOffset.y;
            if (overClear && waterData == 0.0 && position.y + cameraY > SUN_CLOUD_BOTTOM) {
                // Clouds: their alpha is their coverage, faded with distance, and the rest is the clear color
                // showing through. Replace that part with the sky.
                color = original.rgb + (1.0 - alpha) * (skyWithSun - bus.fogColor);
            } else {
                // Terrain, water, entities: vanilla mixed the fog color in by `fog`, and where the surface is
                // translucent with nothing behind it (far water), the clear color shows through by 1 - alpha:
                //     original = alpha * mix(surface, fogColor, fog) + (1 - alpha) * fogColor
                // Take the fog color back out and mix the sky in by `amount` instead, at least as much: more haze
                // with distance (aerial perspective), and a softer fade at the edge of the loaded world.
                float fog = sun_vanilla_fog(bus, position);
                float amount = sun_fog_amount(bus, position, fog);
                vec3 surface = original.rgb - (1.0 - alpha) * bus.fogColor - alpha * fog * bus.fogColor;
                if (terrain) {
                    surface *= sun_relight(faceNormal, levels, bus.sunDirection, bus.rainBrightness,
                                          texelFetch(LightSampler, ivec2(1, 0), 0).rgb, texelFetch(LightSampler, ivec2(2, 0), 0).rgb);
                }
                float keep = (1.0 - amount) / max(1.0 - fog, 1e-4);
                color = surface * keep + alpha * amount * skyColor + (1.0 - alpha) * skyWithSun;
            }
        }
    }

    // Paint the bus column over with its neighbour.
    if (pixel.x == 0) {
        color = texelFetch(InSampler, ivec2(1, pixel.y), 0).rgb;
    }
    float tag = !inAir || waterData == 0.0 ? 1.0 : waterData > 0.75 ? 0.5 : 0.25;
    fragColor = vec4(clamp(color, 0.0, 1.0), tag);
}

#version 330
#extension GL_ARB_separate_shader_objects : require

#include <sun:light_code.glsl>

// Bloom, step 1: the bright parts of the image, into a small target. A pixel glows if it is very bright,
// or if it looks like a light source: bright, saturated (lava, flames, glowstone…), and at full block light,
// read from the light levels opaque terrain writes in alpha. The saturation keeps out what light sources
// light up: sand next to lava is just as bright, but pale.
uniform sampler2D InSampler;     // the image, after the water pass
uniform sampler2D MainSampler;   // minecraft:main, for its alpha

layout(std140) uniform SamplerInfo {
    vec2 OutSize;
    vec2 InSize;
    vec2 MainSize;
};

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

void main() {
    // Average the glowing part of the source pixels this output pixel covers (about 4 x 4).
    vec2 footprint = InSize / OutSize;
    ivec2 first = ivec2((texCoord - 0.5 / OutSize) * InSize);
    vec3 sum = vec3(0.0);
    for (int y = 0; y < 4; y++) {
        for (int x = 0; x < 4; x++) {
            ivec2 p = first + ivec2(vec2(x, y) * footprint / 4.0);
            vec3 c = texelFetch(InSampler, p, 0).rgb;
            float luminance = dot(c, vec3(0.2126, 0.7152, 0.0722));
            float glow = smoothstep(0.95, 1.0, luminance);   // white things in sunlight only just
            vec2 levels;
            float saturation = (max(c.r, max(c.g, c.b)) - min(c.r, min(c.g, c.b))) / max(max(c.r, max(c.g, c.b)), 1e-3);
            if (sun_decode_light(texelFetch(MainSampler, p, 0).a, levels) && levels.x > 0.9) {
                glow = max(glow, 1.5 * smoothstep(0.45, 0.8, luminance) * smoothstep(0.35, 0.6, saturation));
            }
            sum += c * glow;
        }
    }
    fragColor = vec4(sum / 16.0, 1.0);
}

#version 330
#extension GL_ARB_separate_shader_objects : require

// A 9-tap Gaussian blur along one direction (BlurConfig, from the post effect's JSON), with a bilinear
// input: each tap reads two texels at once.
uniform sampler2D InSampler;

layout(std140) uniform SamplerInfo {
    vec2 OutSize;
    vec2 InSize;
};

layout(std140) uniform BlurConfig {
    vec2 Direction;
};

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

void main() {
    const float offsets[3] = float[](0.0, 1.3846153846, 3.2307692308);
    const float weights[3] = float[](0.2270270270, 0.3162162162, 0.0702702703);
    vec2 step = Direction / InSize;
    vec3 sum = texture(InSampler, texCoord).rgb * weights[0];
    for (int i = 1; i < 3; i++) {
        sum += texture(InSampler, texCoord + step * offsets[i]).rgb * weights[i];
        sum += texture(InSampler, texCoord - step * offsets[i]).rgb * weights[i];
    }
    fragColor = vec4(sum, 1.0);
}

#version 330
#extension GL_ARB_separate_shader_objects : require

// The final image: the bloom (two sizes of glow) added on top.
uniform sampler2D InSampler;
uniform sampler2D BloomNearSampler;   // 480 x 270, a tight glow
uniform sampler2D BloomFarSampler;    // 240 x 135, a wide one

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

const float SUN_BLOOM_STRENGTH = 0.6;

void main() {
    vec3 color = texture(InSampler, texCoord).rgb;
    vec3 bloom = texture(BloomNearSampler, texCoord).rgb + texture(BloomFarSampler, texCoord).rgb;
    // Screen blend: the glow brightens without clipping as hard as an addition.
    color = 1.0 - (1.0 - color) * (1.0 - bloom * SUN_BLOOM_STRENGTH * 2.0);
    fragColor = vec4(color, 1.0);
}

#version 330
#extension GL_ARB_separate_shader_objects : require

// Half the size: with a bilinear input, one sample at the center of each 2 x 2 block averages it.
uniform sampler2D InSampler;

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

void main() {
    fragColor = vec4(texture(InSampler, texCoord).rgb, 1.0);
}

#version 330
#extension GL_ARB_separate_shader_objects : require

// Full-screen triangle for post passes, shipped with the pack (vanilla renamed its own in 26.4).
layout(location = 0) out vec2 texCoord;

void main() {
    vec2 uv = vec2((gl_VertexIndex << 1) & 2, gl_VertexIndex & 2);
    gl_Position = vec4(uv * 2.0 - 1.0, 0.0, 1.0);
    texCoord = uv;
}

#version 330
#extension GL_ARB_separate_shader_objects : require

#include <minecraft:globals.glsl>
#include <sun:bus_read.glsl>
#include <sun:atmosphere.glsl>

// The scene's light, into a 4 x 1 target, once per frame:
//  x = 0: exposure for the sky (a float in 4 bytes): the average sky luminance over a few directions sets
//         how bright the sky is drawn, like a camera's automatic exposure. Bounded, so the night stays dark.
//  x = 1: the color of the sky's ambient light, normalized (its largest channel is 1).
//  x = 2: the color of the direct light reaching the ground, normalized: the sun through the atmosphere by
//         day (orange at sunset), the moon by night.
uniform sampler2D InSampler;

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

vec3 sun_normalized(vec3 c) {
    return c / max(max(c.r, max(c.g, c.b)), 1e-6);
}

void main() {
    int x = int(gl_FragCoord.x);
    SunBus bus = sun_read_bus(InSampler);
    if (!bus.present) {
        fragColor = x == 0 ? sun_pack_float(1.0) : vec4(1.0);
        return;
    }
    float altitude = sun_altitude(float(CameraBlockPos.y) - CameraOffset.y);
    if (x == 2) {
        bool day = bus.sunDirection.y > 0.0;
        vec3 l = day ? bus.sunDirection : -bus.sunDirection;
        vec3 t = sun_transmittance_to_light(vec3(0.0, SUN_PLANET_RADIUS + altitude, 0.0), normalize(vec3(l.x, max(l.y, 0.01), l.z)));
        fragColor = vec4(sun_normalized(day ? t : t * SUN_MOON_RADIANCE), 1.0);
        return;
    }
    vec3 sum = vec3(0.0);
    vec3 unused;
    sum += sun_sky(vec3(0.0, 1.0, 0.0), bus.sunDirection, bus.rainBrightness, altitude, unused);
    for (int i = 0; i < 4; i++) {
        float a = float(i) * 0.5 * SUN_PI;
        sum += sun_sky(normalize(vec3(cos(a), 0.25, sin(a))), bus.sunDirection, bus.rainBrightness, altitude, unused);
        sum += sun_sky(normalize(vec3(cos(a), 1.0, sin(a))), bus.sunDirection, bus.rainBrightness, altitude, unused);
    }
    if (x == 1) {
        fragColor = vec4(sun_normalized(sum), 1.0);
        return;
    }
    float luminance = dot(sum / 9.0, vec3(0.2126, 0.7152, 0.0722));
    fragColor = sun_pack_float(clamp(SUN_EXPOSURE_KEY / max(luminance, 1e-6), SUN_EXPOSURE_MIN, SUN_EXPOSURE_MAX));
}

#version 330
#extension GL_ARB_separate_shader_objects : require

#include <minecraft:globals.glsl>
#include <sun:bus_read.glsl>
#include <sun:atmosphere.glsl>
#include <sun:fog.glsl>

// Water: the surface the atmosphere pass tagged is redrawn with waves, reflections and refraction.
//  - Waves: a sum of directional waves gives the surface's slope at each point (the geometry stays flat).
//  - Reflection: a ray marched in screen space against the depth buffer, else the sky in that direction.
//  - Refraction: the vanilla water (what is underneath, tinted), shifted by the waves.
//  - Fresnel: grazing angles reflect more.
uniform sampler2D InSampler;        // the atmosphere pass's output; alpha tags water (0.5 top, 0.25 side)
uniform sampler2D MainSampler;      // minecraft:main, for the data bus
uniform sampler2D DepthSampler;
uniform sampler2D LightSampler;

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

#define SUN_SSR_STEPS 40
#define SUN_WAVE_COUNT 8
const float SUN_FRESNEL_WAVES = 0.25;   // how much of the waves' tilt Fresnel sees
const float SUN_REFLECTION_RIPPLE = 0.04;   // how far, in screen units per unit of tilt, the waves shift the mirrored image
const float SUN_WAVE_STRENGTH = 0.6;   // how much the waves tilt the surface
const float SUN_WAVE_FLATTEN_DISTANCE = 48.0;   // the waves tilt half as much this far away
const float SUN_WAVE_GRAZING_STRENGTH = 0.15;   // and this much, at a grazing angle
const vec3 SUN_WATER_ABSORPTION = vec3(0.30, 0.12, 0.08);

// Smooth value noise in [0, 1], for the irregularity of the waves.
float sun_noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    float a = fract(sin(dot(i, vec2(127.1, 311.7))) * 43758.5453);
    float b = fract(sin(dot(i + vec2(1.0, 0.0), vec2(127.1, 311.7))) * 43758.5453);
    float c = fract(sin(dot(i + vec2(0.0, 1.0), vec2(127.1, 311.7))) * 43758.5453);
    float d = fract(sin(dot(i + vec2(1.0, 1.0), vec2(127.1, 311.7))) * 43758.5453);
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

// Height of the surface (blocks), and its gradient, at world position p (x, z) and time t (seconds).
// Deep-water waves: angular frequency sqrt(g k), rounded to a whole number of periods per 1200 s, the
// period of GameTime, so that the waves don't jump when it wraps.
// footprint: the size of a pixel on the surface, in blocks. A wave shorter than a few pixels can't be shown:
// sampled once per pixel, it turns into rings around the camera (moiré). Each wave fades out before that.
// Pure sines repeat: seen from afar, the sea became regular parallel bands. A slow noise bends the wave fronts
// (it shifts the position each wave sees) and varies each wave's amplitude from place to place. The noise
// depends on the position only, so nothing jumps when GameTime wraps; its own slope is left out of the
// gradient, which it barely changes at that scale.
vec3 sun_waves(vec2 p, float t, float footprint) {
    const vec2 directions[SUN_WAVE_COUNT] = vec2[](vec2(1.0, 0.3), vec2(-0.4, 1.0), vec2(0.8, -0.7),
                                                  vec2(-1.0, -0.2), vec2(0.2, -1.0), vec2(0.9, 0.9),
                                                  vec2(-0.7, 0.6), vec2(0.4, 0.95));
    const float wavelengths[SUN_WAVE_COUNT] = float[](7.3, 4.6, 3.1, 2.2, 1.55, 1.1, 0.8, 0.57);
    vec2 warp = (vec2(sun_noise(p * 0.045), sun_noise(p * 0.045 + 31.7)) - 0.5) * 14.0;
    vec3 sum = vec3(0.0);
    for (int i = 0; i < SUN_WAVE_COUNT; i++) {
        vec2 d = normalize(directions[i]);
        float k = 2.0 * SUN_PI / wavelengths[i];
        float omega = round(sqrt(9.81 * k) * 1200.0 / (2.0 * SUN_PI)) * 2.0 * SUN_PI / 1200.0;
        float variation = 0.3 + 1.4 * sun_noise(p * (0.6 / wavelengths[i] / 8.0) + float(i) * 17.3);
        float amplitude = 0.017 * wavelengths[i] * variation * smoothstep(2.0, 6.0, wavelengths[i] / footprint);
        float phase = k * dot(d, p + warp * (0.5 + 0.1 * float(i))) - omega * t;
        sum += amplitude * vec3(sin(phase), k * cos(phase) * d);
    }
    return sum;
}

float sun_fresnel(float cosTheta) {
    return 0.02 + 0.98 * pow(1.0 - clamp(cosTheta, 0.0, 1.0), 5.0);
}

// March the reflected ray in view space; on a hit, where on the screen (xy) and how much to trust it (z).
vec3 sun_screen_space_reflection(SunBus bus, vec3 origin, vec3 direction) {
    float stepLength = 0.3 + 0.01 * length(origin);
    vec3 previous = origin;
    vec3 position = origin;
    for (int i = 0; i < SUN_SSR_STEPS; i++) {
        position += direction * stepLength;
        vec4 clip = bus.proj * vec4(position, 1.0);
        if (clip.w <= 0.0) {
            break;
        }
        vec2 uv = clip.xy / clip.w * 0.5 + 0.5;
        if (any(lessThan(uv, vec2(0.0))) || any(greaterThan(uv, vec2(1.0)))) {
            break;
        }
        float depth = texture(DepthSampler, uv).r;
        if (depth > 0.0) {
            float behind = sun_view_position(bus, uv, depth).z - position.z;   // > 0: the ray went behind the scene
            if (behind > 0.0 && behind < stepLength * 3.0 + 0.5) {
                // Refine between the last two points.
                vec3 a = previous;
                vec3 b = position;
                for (int j = 0; j < 5; j++) {
                    vec3 m = 0.5 * (a + b);
                    vec4 c = bus.proj * vec4(m, 1.0);
                    vec2 muv = c.xy / c.w * 0.5 + 0.5;
                    float md = texture(DepthSampler, muv).r;
                    if (md > 0.0 && sun_view_position(bus, muv, md).z > m.z) {
                        b = m;
                        uv = muv;
                    } else {
                        a = m;
                    }
                }
                vec2 edge = smoothstep(vec2(0.0), vec2(0.08), min(uv, 1.0 - uv));
                float trust = edge.x * edge.y * (1.0 - float(i) / float(SUN_SSR_STEPS));
                return vec3(uv, trust);
            }
        }
        previous = position;
        stepLength *= 1.12;
    }
    return vec3(0.0);
}

void main() {
    vec4 color = texture(InSampler, texCoord);
    SunBus bus = sun_read_bus(MainSampler);
    float depth = texture(DepthSampler, texCoord).r;
    vec3 viewPosition = sun_view_position(bus, texCoord, max(depth, 1e-6));
    vec3 position = bus.viewToWorld * viewPosition;
    vec3 faceNormal = normalize(cross(dFdx(position), dFdy(position)));   // derivatives: before any branch
    fragColor = vec4(color.rgb, 1.0);
    if (color.a > 0.9 || !bus.present) {
        return;   // not water, or the atmosphere pass was inactive
    }
    bool top = color.a > 0.375;
    float exposure = sun_unpack_float(texelFetch(LightSampler, ivec2(0, 0), 0));
    vec3 cameraPosition = vec3(CameraBlockPos) - CameraOffset;
    vec3 view = normalize(position);
    float dist = length(position);

    // Surface normal: waves on horizontal surfaces.
    if (dot(faceNormal, view) > 0.0) {
        faceNormal = -faceNormal;
    }
    vec3 normal = faceNormal;
    if (top) {
        // A pixel's size on the water: its angular size times the distance, stretched at grazing angles.
        float footprint = dist * 2.0 / (bus.proj[1][1] * ScreenSize.y) / max(abs(view.y), 0.05);
        vec3 wave = sun_waves((position + cameraPosition).xz, GameTime * 1200.0, footprint);
        // At a grazing angle, even a small tilt sends the reflection to the sky: the sea stops mirroring the
        // land behind it. So the waves tilt less the flatter the view, and also with distance.
        float grazing = mix(SUN_WAVE_GRAZING_STRENGTH, 1.0, smoothstep(0.02, 0.25, abs(view.y)));
        float strength = SUN_WAVE_STRENGTH * grazing / (1.0 + dist / SUN_WAVE_FLATTEN_DISTANCE);
        normal = normalize(vec3(-wave.y * strength, 1.0, -wave.z * strength));
        if (faceNormal.y < 0.0) {
            normal.y = -normal.y;   // seen from below
        }
    }

    // Reflection: the screen first, the sky where the ray leaves it.
    vec3 reflected = reflect(view, normal);
    if (top && reflected.y * normal.y < 0.0) {
        reflected.y = -reflected.y;   // a steep wave can't reflect into the water
    }
    float altitude = sun_altitude(cameraPosition.y);
    vec3 transmittance;
    vec3 skyLinear = sun_sky(reflected, bus.sunDirection, bus.rainBrightness, altitude, transmittance);
    // The sun's glint: its disc, and a wider lobe for the small waves the normal can't show.
    float glint = pow(max(dot(reflected, bus.sunDirection), 0.0), 600.0) * 2.0;
    skyLinear += sun_sun_disc(reflected, bus.sunDirection, transmittance, bus.rainBrightness)
               + SUN_SUN_RADIANCE * transmittance * glint * bus.rainBrightness;
    vec3 reflection = sun_tonemap(skyLinear * exposure);
    vec3 viewNormal = mat3(transpose(bus.viewToWorld)) * normal;
    // The screen is searched along the reflection of the flat surface, and the waves only shift where its
    // color is read. Searched along the waves' own reflection, a grazing ray hit the land or missed it
    // depending on the slightest tilt, and the sea stopped mirroring what stands behind it.
    mat3 worldToView = mat3(transpose(bus.viewToWorld));
    vec3 viewFace = worldToView * faceNormal;
    vec3 hit = sun_screen_space_reflection(bus, viewPosition + viewFace * 0.05, worldToView * reflect(view, faceNormal));
    if (hit.z > 0.0) {
        vec2 ripple = (viewNormal.xy - viewFace.xy) * SUN_REFLECTION_RIPPLE;
        vec2 uv = hit.xy + ripple;
        vec4 there = texture(InSampler, uv);
        // Keep the shifted read if it lands on screen and not on the water itself.
        vec3 mirrored = there.a > 0.9 && all(greaterThan(uv, vec2(0.0))) && all(lessThan(uv, vec2(1.0)))
                      ? there.rgb : texture(InSampler, hit.xy).rgb;
        reflection = mix(reflection, mirrored, hit.z);
    }

    // Distance fog on the reflection, as on everything else (the refraction already has it).
    vec3 unused;
    vec3 skyAlongView = sun_tonemap(sun_sky(view, bus.sunDirection, bus.rainBrightness, altitude, unused) * exposure);
    float fogAmount = sun_fog_amount(bus, position, sun_vanilla_fog(bus, position));
    reflection = mix(reflection, skyAlongView, fogAmount);

    // Refraction: the vanilla water, shifted by the waves, if the shifted pixel is still water.
    vec2 shifted = texCoord + (viewNormal.xy - (mat3(transpose(bus.viewToWorld)) * faceNormal).xy) * 0.03;
    vec4 under = texture(InSampler, shifted);
    vec3 refraction = under.a < 0.9 ? under.rgb : color.rgb;
    // Absorption: the seabed's depth is unknown (water writes its own depth), but at grazing angles light
    // crosses more water, so the refraction darkens toward blue-green with the angle. Not the part that is
    // already fog.
    float path = 1.0 / max(dot(-view, faceNormal), 0.15);
    refraction = mix(refraction * exp(-SUN_WATER_ABSORPTION * path), refraction, fogAmount);

    // At a grazing angle, Fresnel swings from 0.8 to 0.3 with a slight tilt: with the waves' full normal, the
    // reflection gave way to the water's blue. The waves only take part in it a little.
    float fresnel = sun_fresnel(dot(-view, normalize(mix(faceNormal, normal, SUN_FRESNEL_WAVES))));
    fragColor = vec4(mix(refraction, reflection, fresnel), 1.0);
}

#ifndef SUN_ATMOSPHERE_GLSL
#define SUN_ATMOSPHERE_GLSL

// Sky from single scattering in an Earth-like atmosphere: Rayleigh scattering (air molecules, the blue
// sky), Mie scattering (aerosols, the glow around the sun) and ozone absorption (the deep blue of
// twilight). Ray-marched per pixel, in meters, with the planet's center below the camera.
// Coefficients: Bruneton & Neyret 2008, Hillaire 2020.

#define SUN_VIEW_STEPS 16
#define SUN_LIGHT_STEPS 4

const float SUN_PI = 3.14159265;
const float SUN_PLANET_RADIUS = 6360e3;
const float SUN_ATMOSPHERE_RADIUS = 6460e3;
const vec3 SUN_RAYLEIGH_SCATTERING = vec3(5.802e-6, 13.558e-6, 33.1e-6);
const float SUN_MIE_SCATTERING = 3.996e-6;
const float SUN_MIE_EXTINCTION = 4.440e-6;
const float SUN_MIE_G = 0.8;
const vec3 SUN_OZONE_ABSORPTION = vec3(0.650e-6, 1.881e-6, 0.085e-6);

const vec3 SUN_SUN_RADIANCE = vec3(20.0);
const vec3 SUN_MOON_RADIANCE = vec3(0.020, 0.024, 0.032);   // dimmer and slightly blue: night vision
const vec3 SUN_NIGHT_GLOW = vec3(0.0006, 0.0008, 0.0016);   // airglow and starlight, so night is never black
// Automatic exposure (post/exposure): exposure = key / average sky luminance, within these bounds.
const float SUN_EXPOSURE_KEY = 0.28;
const float SUN_EXPOSURE_MIN = 0.05;
const float SUN_EXPOSURE_MAX = 30.0;
// Distance, in blocks, over which the haze of the air covers about 63% of what is behind it.
const float SUN_HAZE_DISTANCE = 900.0;

// Translucent pixels above this height are clouds (the overworld's cloud_height is 192.33).
const float SUN_CLOUD_BOTTOM = 190.0;

const float SUN_SUN_COS_RADIUS = 0.99985;                    // about 1 degree: bigger than the real sun, reads better

// Density of air, aerosols and ozone at height h, relative to sea level.
vec3 sun_density(float h) {
    return vec3(exp(-h / 8000.0), exp(-h / 1200.0), max(0.0, 1.0 - abs(h - 25000.0) / 15000.0));
}

vec3 sun_extinction(vec3 opticalDepth) {
    return SUN_RAYLEIGH_SCATTERING * opticalDepth.x + SUN_MIE_EXTINCTION * opticalDepth.y + SUN_OZONE_ABSORPTION * opticalDepth.z;
}

// Distance from o (inside the sphere) to where the ray leaves the sphere of radius r centered on the origin.
float sun_sphere_exit(vec3 o, vec3 d, float r) {
    float b = dot(o, d);
    float c = dot(o, o) - r * r;
    return -b + sqrt(max(b * b - c, 0.0));
}

// Distance to where the ray enters the sphere from outside, or -1.
float sun_sphere_entry(vec3 o, vec3 d, float r) {
    float b = dot(o, d);
    float c = dot(o, o) - r * r;
    float h = b * b - c;
    if (h < 0.0) {
        return -1.0;
    }
    return -b - sqrt(h);
}

// Fraction of light that reaches p from direction l, through the rest of the atmosphere.
vec3 sun_transmittance_to_light(vec3 p, vec3 l) {
    if (sun_sphere_entry(p, l, SUN_PLANET_RADIUS) > 0.0) {
        return vec3(0.0);   // behind the planet
    }
    float dt = sun_sphere_exit(p, l, SUN_ATMOSPHERE_RADIUS) / float(SUN_LIGHT_STEPS);
    vec3 depth = vec3(0.0);
    for (int i = 0; i < SUN_LIGHT_STEPS; i++) {
        depth += sun_density(length(p + l * ((float(i) + 0.5) * dt)) - SUN_PLANET_RADIUS) * dt;
    }
    return exp(-sun_extinction(depth));
}

// Light scattered toward the camera along direction d, from a light in direction l with radiance 1.
// transmittance: how much of what is behind the atmosphere along d gets through (for the sun disc).
vec3 sun_scattering(vec3 d, vec3 l, float altitude, out vec3 transmittance) {
    vec3 o = vec3(0.0, SUN_PLANET_RADIUS + altitude, 0.0);
    float rayLength = sun_sphere_exit(o, d, SUN_ATMOSPHERE_RADIUS);
    float mu = dot(d, l);
    float phaseRayleigh = 3.0 / (16.0 * SUN_PI) * (1.0 + mu * mu);
    float g2 = SUN_MIE_G * SUN_MIE_G;
    float phaseMie = 3.0 / (8.0 * SUN_PI) * (1.0 - g2) * (1.0 + mu * mu)
                   / ((2.0 + g2) * pow(1.0 + g2 - 2.0 * SUN_MIE_G * mu, 1.5));
    vec3 depth = vec3(0.0);
    vec3 sum = vec3(0.0);
    // Steps grow quadratically: dense air near the camera gets most of them.
    for (int i = 0; i < SUN_VIEW_STEPS; i++) {
        float t0 = rayLength * pow(float(i) / float(SUN_VIEW_STEPS), 2.0);
        float t1 = rayLength * pow(float(i + 1) / float(SUN_VIEW_STEPS), 2.0);
        float dt = t1 - t0;
        vec3 p = o + d * (0.5 * (t0 + t1));
        vec3 density = sun_density(length(p) - SUN_PLANET_RADIUS);
        vec3 toCamera = exp(-sun_extinction(depth + density * (0.5 * dt)));
        vec3 scatter = SUN_RAYLEIGH_SCATTERING * density.x * phaseRayleigh + SUN_MIE_SCATTERING * density.y * phaseMie;
        sum += toCamera * sun_transmittance_to_light(p, l) * scatter * dt;
        depth += density * dt;
    }
    transmittance = exp(-sun_extinction(depth));
    return sum;
}

// Linear radiance of the sky in world direction dir, without the sun disc. The ground below the horizon
// is not modeled: directions below it look at the horizon, darkened.
vec3 sun_sky(vec3 dir, vec3 sunDirection, float rainBrightness, float altitude, out vec3 transmittance) {
    vec3 d = normalize(vec3(dir.x, max(dir.y, 0.0), dir.z));
    vec3 color = SUN_NIGHT_GLOW;
    transmittance = vec3(1.0);
    if (sunDirection.y > -0.3) {
        color += sun_scattering(d, sunDirection, altitude, transmittance) * SUN_SUN_RADIANCE;
    }
    if (-sunDirection.y > -0.3) {
        vec3 unused;
        color += sun_scattering(d, -sunDirection, altitude, unused) * SUN_MOON_RADIANCE;
    }
    color *= mix(1.0, 0.25, smoothstep(0.0, -0.3, dir.y));
    // Rain: a grey, darker overcast sky.
    float luminance = dot(color, vec3(0.2126, 0.7152, 0.0722));
    return mix(color, vec3(luminance * 0.45), (1.0 - rainBrightness) * 0.9);
}

// Linear radiance of the sun disc in direction dir, seen through the atmosphere.
vec3 sun_sun_disc(vec3 dir, vec3 sunDirection, vec3 transmittance, float rainBrightness) {
    float c = dot(dir, sunDirection);
    if (c < SUN_SUN_COS_RADIUS - 0.0001 || dir.y < 0.0) {
        return vec3(0.0);
    }
    float edge = smoothstep(SUN_SUN_COS_RADIUS - 0.0001, SUN_SUN_COS_RADIUS + 0.00002, c);
    // Limb darkening: the edge of the disc is dimmer than its center.
    float r = sqrt(clamp((1.0 - c) / (1.0 - SUN_SUN_COS_RADIUS), 0.0, 1.0));
    float limb = 0.4 + 0.6 * sqrt(1.0 - r * r);
    return SUN_SUN_RADIANCE * 40.0 * transmittance * edge * limb * rainBrightness * rainBrightness;
}

// Height of the camera above the sea, in meters, from its block height: the overworld sea is at y = 63.
float sun_altitude(float cameraY) {
    return clamp(200.0 + (cameraY - 63.0) * 2.0, 20.0, 4000.0);
}

// ACES filmic curve (Narkowicz 2015), then sRGB-like gamma.
vec3 sun_tonemap(vec3 linear) {
    vec3 x = linear;
    vec3 mapped = clamp(x * (2.51 * x + 0.03) / (x * (2.43 * x + 0.59) + 0.14), 0.0, 1.0);
    return pow(mapped, vec3(1.0 / 2.2));
}

#endif

#ifndef SUN_BUS_GLSL
#define SUN_BUS_GLSL

// Data bus.
//
// Column x = 0 of the screen carries values from core shaders to the post effects. Every program that
// draws the world discards its fragments in that column (SUN_PROTECT_BUS), and the writers relocate
// their geometry onto a strip of it. The post effects read the values, then paint the column over.
//
// Rows, numbered from NDC y = -1 (the bottom of the screen):
#define SUN_ROW_MARKER 0      // magenta: the bus was written this frame
#define SUN_ROW_PROJ 1        // ProjMat, 16 floats, column-major
#define SUN_ROW_VIEW 17       // view rotation (the sky's ModelViewMat), 16 floats, column-major
#define SUN_ROW_SKY 33        // sky color (ColorModulator of the sky disc), 3 channels
#define SUN_ROW_FOG 34        // FogColor
#define SUN_ROW_FOG_PARAMS 35 // 6 floats: FogEnvironmentalStart, FogEnvironmentalEnd, FogRenderDistanceStart,
                             // FogRenderDistanceEnd, FogSkyEnd, FogCloudsEnd
#define SUN_SKY_ROWS 41       // rows written by the sky
#define SUN_ROW_SUN 41        // view-space sun direction (3 components), then the rain brightness mapped to [-1, 1]:
#define SUN_SUN_ROWS 4        // 24-bit fixed point each
// The sun is drawn with additive blending (color = src * alpha + dst), after the sky: the sky clears the
// sun's rows to black first, so the sum is exactly what the sun writes.
#define SUN_SKY_STRIP_ROWS 45 // rows covered by the sky's strip: its own values, then the cleared sun rows

// Discard fragments that would land on the bus column. Orthographic renders (the GUI, and the GUI item
// atlas, which core/item draws into) are left alone: they happen elsewhere or after the post effects.
// Needs ProjMat (#include <minecraft:projection.glsl>).
#define SUN_PROTECT_BUS if (gl_FragCoord.x < 1.0 && ProjMat[2][3] != 0.0) { discard; }
// For full-screen copies onto the world (blit_screen), which have no ProjMat.
#define SUN_PROTECT_BUS_ALWAYS if (gl_FragCoord.x < 1.0) { discard; }

// A float as 4 bytes (RGBA). Only for writers without blending: the alpha channel is part of the value.
vec4 sun_pack_float(float v) {
    uint b = floatBitsToUint(v);
    return vec4(float((b >> 24u) & 255u), float((b >> 16u) & 255u), float((b >> 8u) & 255u), float(b & 255u)) / 255.0;
}

float sun_unpack_float(vec4 c) {
    uvec4 b = uvec4(round(c * 255.0));
    return uintBitsToFloat((b.x << 24u) | (b.y << 16u) | (b.z << 8u) | b.w);
}

// A value in [-1, 1] as 24-bit fixed point in RGB, alpha 1: safe for writers with alpha blending.
vec4 sun_pack_signed(float v) {
    uint q = uint(round(clamp(v * 0.5 + 0.5, 0.0, 1.0) * 16777215.0));
    return vec4(float((q >> 16u) & 255u), float((q >> 8u) & 255u), float(q & 255u), 255.0) / 255.0;
}

float sun_unpack_signed(vec4 c) {
    uvec3 b = uvec3(round(c.rgb * 255.0));
    return float((b.x << 16u) | (b.y << 8u) | b.z) / 16777215.0 * 2.0 - 1.0;
}

// Clip-space position of a corner of the strip covering bus rows [firstRow, firstRow + rows).
// corner is (0 or 1, 0 or 1). Corners (0,0), (1,0), (1,1), (0,1) in that order are front-facing.
vec4 sun_strip_corner(vec2 corner, int firstRow, int rows, vec2 screenSize) {
    vec2 pixel = vec2(corner.x, float(firstRow) + corner.y * float(rows));
    return vec4(-1.0 + 2.0 * pixel / screenSize, 0.0, 1.0);
}

#endif

#ifndef SUN_BUS_READ_GLSL
#define SUN_BUS_READ_GLSL

#include <sun:bus.glsl>

// Reading the data bus in a post effect, from an input bound to minecraft:main.

struct SunBus {
    bool present;
    mat4 proj;
    mat4 invProj;
    mat3 viewToWorld;     // camera-relative world axes from view space (the inverse of the view rotation)
    bool zZeroToOne;      // depth range of the backend: [0, 1] (Vulkan) or [-1, 1] (OpenGL without clip control)
    vec3 skyColor;
    vec3 fogColor;        // also the color the frame was cleared to
    float fogEnvironmentalStart;
    float fogEnvironmentalEnd;
    float fogRenderDistanceStart;
    float fogRenderDistanceEnd;
    float fogSkyEnd;
    float fogCloudsEnd;
    vec3 sunDirection;    // world space
    float rainBrightness; // 1: clear, 0: full rain
};

vec4 sun_bus_texel(sampler2D bus, int row, bool fromBottom) {
    int height = textureSize(bus, 0).y;
    return texelFetch(bus, ivec2(0, fromBottom ? row : height - 1 - row), 0);
}

bool sun_is_marker(vec4 c) {
    return all(lessThan(abs(c.rgb - vec3(1.0, 0.0, 1.0)), vec3(0.01)));
}

SunBus sun_read_bus(sampler2D bus) {
    SunBus b;
    // Texel row 0 is the bottom of the screen on both backends; the top row is checked too, just in case.
    bool fromBottom = sun_is_marker(texelFetch(bus, ivec2(0, 0), 0));
    b.present = fromBottom || sun_is_marker(texelFetch(bus, ivec2(0, textureSize(bus, 0).y - 1), 0));
    if (!b.present) {
        return b;
    }
    mat4 view;
    for (int i = 0; i < 16; i++) {
        b.proj[i / 4][i % 4] = sun_unpack_float(sun_bus_texel(bus, SUN_ROW_PROJ + i, fromBottom));
        view[i / 4][i % 4] = sun_unpack_float(sun_bus_texel(bus, SUN_ROW_VIEW + i, fromBottom));
    }
    b.invProj = inverse(b.proj);
    b.viewToWorld = transpose(mat3(view));
    // Reversed depth (near 1, far 0) with JOML's perspective: proj[2][2] = near / (far - near) for a [0, 1]
    // depth range, (far + near) / (far - near) for [-1, 1].
    b.zZeroToOne = b.proj[2][2] < 0.5;
    b.skyColor = sun_bus_texel(bus, SUN_ROW_SKY, fromBottom).rgb;
    b.fogColor = sun_bus_texel(bus, SUN_ROW_FOG, fromBottom).rgb;
    float fog[6];
    for (int i = 0; i < 6; i++) {
        fog[i] = sun_unpack_float(sun_bus_texel(bus, SUN_ROW_FOG_PARAMS + i, fromBottom));
    }
    b.fogEnvironmentalStart = fog[0];
    b.fogEnvironmentalEnd = fog[1];
    b.fogRenderDistanceStart = fog[2];
    b.fogRenderDistanceEnd = fog[3];
    b.fogSkyEnd = fog[4];
    b.fogCloudsEnd = fog[5];
    vec3 sunView = vec3(sun_unpack_signed(sun_bus_texel(bus, SUN_ROW_SUN, fromBottom)),
                        sun_unpack_signed(sun_bus_texel(bus, SUN_ROW_SUN + 1, fromBottom)),
                        sun_unpack_signed(sun_bus_texel(bus, SUN_ROW_SUN + 2, fromBottom)));
    b.sunDirection = normalize(b.viewToWorld * sunView);
    b.rainBrightness = sun_unpack_signed(sun_bus_texel(bus, SUN_ROW_SUN + 3, fromBottom)) * 0.5 + 0.5;
    return b;
}

// Camera-relative position, in view space, of the point at this screen position and depth.
vec3 sun_view_position(SunBus b, vec2 texCoord, float depth) {
    float z = b.zZeroToOne ? depth : depth * 2.0 - 1.0;
    vec4 p = b.invProj * vec4(texCoord * 2.0 - 1.0, z, 1.0);
    return p.xyz / p.w;
}

// Whether the camera is in plain air, from the fog the game set up (FogRenderer and the fog environments).
// In air, the sky fog ends at the render distance (capped at 512 blocks), before the environmental fog does.
// In water and under darkness, it ends with the environmental fog; under blindness, at 0.8 times it.
bool sun_in_air(SunBus b) {
    return abs(b.fogSkyEnd - min(b.fogRenderDistanceEnd, 512.0)) < 1.0 && b.fogSkyEnd < b.fogEnvironmentalEnd - 1.0;
}

#endif

#ifndef SUN_FOG_GLSL
#define SUN_FOG_GLSL

#include <sun:bus_read.glsl>
#include <sun:atmosphere.glsl>

// The fog, recomputed in post effects from a pixel's camera-relative position and the fog distances of
// the bus, and the stronger fog the pack uses instead.

float sun_linear_fog(float distance, float start, float end) {
    return clamp((distance - start) / max(end - start, 1e-3), 0.0, 1.0);
}

// How much of the fog color vanilla mixed in at this position (fog.glsl, for terrain and entities).
float sun_vanilla_fog(SunBus bus, vec3 position) {
    float spherical = length(position);
    float cylindrical = max(length(position.xz), abs(position.y));
    return max(sun_linear_fog(spherical, bus.fogEnvironmentalStart, bus.fogEnvironmentalEnd),
               sun_linear_fog(cylindrical, bus.fogRenderDistanceStart, bus.fogRenderDistanceEnd));
}

// How much of the sky the pack mixes in instead, at least vanilla's: a haze that grows with distance
// (aerial perspective), and a softer fade at the edge of the loaded world.
float sun_fog_amount(SunBus bus, vec3 position, float vanillaFog) {
    float cylindrical = max(length(position.xz), abs(position.y));
    float edge = smoothstep(0.5, 0.95, cylindrical / bus.fogRenderDistanceEnd);
    float haze = 1.0 - exp(-length(position) / SUN_HAZE_DISTANCE);
    return 1.0 - (1.0 - max(vanillaFog, edge)) * (1.0 - haze);
}

#endif

#ifndef SUN_LIGHT_CODE_GLSL
#define SUN_LIGHT_CODE_GLSL

// Light levels in the alpha of opaque terrain (solid and cutout blocks), for the post effects.
//
// The alpha of minecraft:main then has three ranges:
//   0 to 204:   translucent things in front of the clear color: clouds (at most 0.8), far water, glass;
//   205 to 252: opaque terrain, with 8 sky light levels x 6 block light levels;
//   255:        anything else that is opaque (entities, block entities…), left as it is.

// levels: (block, sky), each 0 to 1 (light level / 15).
float sun_encode_light(vec2 levels) {
    float sky = round(clamp(levels.y, 0.0, 1.0) * 7.0);
    float block = round(clamp(levels.x, 0.0, 1.0) * 5.0);
    return (205.0 + sky * 6.0 + block) / 255.0;
}

bool sun_decode_light(float alpha, out vec2 levels) {
    float v = round(alpha * 255.0) - 205.0;
    levels = vec2(mod(v, 6.0) / 5.0, floor(v / 6.0) / 7.0);
    return v >= 0.0 && v <= 47.0;
}

#endif

#ifndef SUN_LIGHTING_GLSL
#define SUN_LIGHTING_GLSL

// Relighting opaque terrain. The vanilla image already holds albedo x light, and only the light levels are
// known, so the pack changes the light by a factor instead of computing it from scratch:
//
//   factor = (light from the sky the pack wants) / (light from the sky vanilla gave)
//
// mixed with 1 by the share of sky light in the pixel (block light is left alone). Vanilla's sky light is
// uniform but for a fixed shade per face (CardinalLighting.DEFAULT: up 1, down 0.5, north and south 0.8,
// east and west 0.6). The pack's is an ambient sky light, brighter on faces that see more sky, plus a direct
// light from the sun (the moon by night) along the face's normal. Both are normalized so that a face
// pointing up keeps vanilla's brightness: the overall level of day and night stays vanilla's, only the
// direction and the color change.

const float SUN_DIRECT_SHARE = 0.45;   // share of the direct light on a face that faces it, by day
const float SUN_MOON_SHARE = 0.3;      // the same, by night
const float SUN_AMBIENT_TINT = 0.3;    // how much of the sky's color the ambient light keeps (0: white)
const float SUN_DIRECT_TINT = 0.7;     // the same for the direct light (orange at sunset)

// Vanilla's light curve for a level from 0 to 1 (the lightmap's brightness, before gamma).
float sun_light_curve(float level) {
    return level / (4.0 - 3.0 * level);
}

vec3 sun_relight(vec3 faceNormal, vec2 levels, vec3 sunDirection, float rainBrightness, vec3 ambientColor, vec3 directColor) {
    // The face's axis: the normal from depth derivatives is exact on flat faces, noisy on edges.
    // Surfaces that face no axis are plants (two diagonal quads, which vanilla doesn't shade) or block
    // edges: they keep vanilla's brightness, and only take the light's color.
    vec3 m = abs(faceNormal);
    vec3 n;
    float vanillaShade;
    if (max(m.x, max(m.y, m.z)) < 0.9) {
        n = vec3(0.0, 1.0, 0.0);
        vanillaShade = 1.0;
    } else if (m.y >= m.x && m.y >= m.z) {
        n = vec3(0.0, sign(faceNormal.y), 0.0);
        vanillaShade = faceNormal.y > 0.0 ? 1.0 : 0.5;
    } else if (m.z >= m.x) {
        n = vec3(0.0, 0.0, sign(faceNormal.z));
        vanillaShade = 0.8;
    } else {
        n = vec3(sign(faceNormal.x), 0.0, 0.0);
        vanillaShade = 0.6;
    }

    // Light colors with a luminance of 1, partly desaturated: a fully blue sky light turns sand blue.
    const vec3 luma = vec3(0.2126, 0.7152, 0.0722);
    ambientColor = mix(vec3(1.0), ambientColor / max(dot(ambientColor, luma), 1e-3), SUN_AMBIENT_TINT);
    directColor = mix(vec3(1.0), directColor / max(dot(directColor, luma), 1e-3), SUN_DIRECT_TINT);

    bool day = sunDirection.y > 0.0;
    vec3 l = day ? sunDirection : -sunDirection;
    float direct = (day ? SUN_DIRECT_SHARE : SUN_MOON_SHARE) * smoothstep(0.0, 0.15, l.y) * rainBrightness * rainBrightness;
    vec3 ambient = ambientColor * (1.0 - direct);
    vec3 light = ambient * (0.8 + 0.2 * n.y) + directColor * direct * max(dot(n, l), 0.0);   // sides see less sky
    vec3 up = ambient + directColor * direct * l.y;
    vec3 skyFactor = light / max(dot(up, luma), 1e-3) / vanillaShade;
    skyFactor = clamp(skyFactor, vec3(0.3), vec3(1.6));

    // Share of the sky in the pixel's light. Vanilla dims sky light at night, not block light.
    float daylight = mix(0.25, 1.0, smoothstep(-0.2, 0.2, sunDirection.y));
    float sky = sun_light_curve(levels.y) * daylight;
    float share = sky / max(sky + sun_light_curve(levels.x), 1e-3);
    return mix(vec3(1.0), skyFactor, share);
}

#endif

#ifndef SUN_WATER_GLSL
#define SUN_WATER_GLSL

// Water markers. The terrain shaders (vanilla and Sodium) recognize water fragments, and on every even
// screen column write a marker instead of the water color, with alpha 1 so that blending keeps it exact.
// Odd columns keep the vanilla water, blended over what is underneath: the post effects take the
// refraction color from them, and redraw the surface.
//
// Water textures (water_still, water_flow, water_overlay) have a uniform alpha of 180/255. The slime block
// shares it, but water is tinted by the biome and slime is not.
#define SUN_WATER_ALPHA 180.0

bool sun_is_water(vec4 textureColor, vec4 tint) {
    return abs(textureColor.a * 255.0 - SUN_WATER_ALPHA) < 0.5
        && max(tint.r, max(tint.g, tint.b)) - min(tint.r, min(tint.g, tint.b)) > 0.05;
}

// The marker of column x: two bytes that depend on x, so that a scene color matches by chance with a
// probability of 1 in 65536 per pixel, and only where it is also at the right place. Only x is used:
// gl_FragCoord.y doesn't count from the same edge on every backend. The third byte carries data.
vec4 sun_water_marker(int x, float data) {
    return vec4(float((x * 73 + 11) & 255) / 255.0, float((x * 197 + 89) & 255) / 255.0, data, 1.0);
}

bool sun_is_water_marker(vec4 c, int x) {
    vec4 m = sun_water_marker(x, 0.0);
    return (x & 1) == 0 && abs(c.r - m.r) < 0.5 / 255.0 && abs(c.g - m.g) < 0.5 / 255.0;
}

// The data byte: 1 for a horizontal surface (the top of water, or its bottom seen from below), 0.5 for a side.
float sun_water_data(vec3 cameraRelativePosition) {
    vec3 n = normalize(cross(dFdx(cameraRelativePosition), dFdy(cameraRelativePosition)));
    return abs(n.y) > 0.7 ? 1.0 : 0.5;
}

#endif

